import json,os,signal,time,base64,subprocess,shutil
assert not (budget_root/'training/successful_ids.jsonl').exists()
state=json.loads((budget_root/'orchestration_status.json').read_text());assert state['state']=='UNSLOTH_WORKER_RUNNING'
