print(json.dumps({'state':'T4_NATIVE_CAPABILITY_CHECK_CORRECTED','reason':'torch is_bf16_supported includes software emulation; hardware7.5 remains FP16','prior_optimizer_updates':0,'orchestrator_pid':budget_process.pid}))
